<title>Conway's Game of Life — B3/S23</title>
<style>
  :root{
    --ink:#0b1619;
    --panel:#0f2126;
    --panel2:#0d1c20;
    --line:rgba(122,208,192,.14);
    --mint:#5fe3a1;
    --amber:#ffcf5e;
    --amber-deep:#ffb85c;
    --coral:#ff6f5e;
    --cyan:#7ad0e0;
    --text:#e9f5ef;
    --dim:#8fb3ab;
    --display:Impact,Haettenschweiler,"Franklin Gothic Bold","Arial Black",sans-serif;
    --body:"Trebuchet MS","Segoe UI",Verdana,sans-serif;
    --mono:ui-monospace,"SF Mono","Cascadia Mono",Menlo,Consolas,"Courier New",monospace;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    font-family:var(--body);
    color:var(--text);
    background:
      radial-gradient(1100px 700px at 72% -12%, rgba(64,190,160,.14), transparent 60%),
      radial-gradient(900px 650px at 8% 112%, rgba(255,190,100,.09), transparent 60%),
      var(--ink);
    display:flex;flex-direction:column;align-items:center;
    padding:28px 16px 40px;
    overflow-x:hidden;
  }
  /* faint blueprint texture */
  body::before{
    content:"";position:fixed;inset:0;pointer-events:none;z-index:0;
    background-image:
      linear-gradient(rgba(122,208,192,.05) 1px,transparent 1px),
      linear-gradient(90deg,rgba(122,208,192,.05) 1px,transparent 1px);
    background-size:28px 28px;
    -webkit-mask-image:radial-gradient(ellipse at 50% 38%,#000 25%,transparent 78%);
            mask-image:radial-gradient(ellipse at 50% 38%,#000 25%,transparent 78%);
  }
  /* drifting spores */
  .bg{position:fixed;inset:0;pointer-events:none;z-index:0}
  .bg i{position:absolute;border-radius:50%;filter:blur(1.5px);opacity:.45;
        animation:drift 16s ease-in-out infinite alternate}
  .bg i:nth-child(1){width:9px;height:9px;left:9%;top:72%;background:var(--mint);animation-duration:19s}
  .bg i:nth-child(2){width:5px;height:5px;left:16%;top:24%;background:var(--amber);animation-duration:14s;animation-delay:-4s}
  .bg i:nth-child(3){width:7px;height:7px;left:86%;top:64%;background:var(--cyan);animation-duration:22s;animation-delay:-9s}
  .bg i:nth-child(4){width:4px;height:4px;left:78%;top:18%;background:var(--mint);animation-duration:12s;animation-delay:-2s}
  .bg i:nth-child(5){width:6px;height:6px;left:64%;top:86%;background:var(--amber);animation-duration:24s;animation-delay:-12s}
  .bg i:nth-child(6){width:10px;height:10px;left:38%;top:8%;background:rgba(95,227,161,.6);animation-duration:27s;animation-delay:-6s}
  @keyframes drift{from{transform:translate3d(0,0,0)}to{transform:translate3d(34px,-64px,0)}}

  main{position:relative;z-index:1;width:min(660px,100%)}

  header{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;flex-wrap:wrap;margin-bottom:18px}
  .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.32em;color:var(--mint);margin-bottom:6px}
  h1{font-family:var(--display);font-weight:400;font-size:clamp(40px,7vw,60px);
     line-height:.95;letter-spacing:.02em;color:var(--text)}
  h1 span{color:var(--amber);text-shadow:0 0 26px rgba(255,207,94,.35)}
  .readout{display:flex;gap:22px}
  .stat{text-align:right}
  .stat b{display:block;font-family:var(--mono);font-size:27px;font-weight:700;
          color:var(--text);font-variant-numeric:tabular-nums;line-height:1}
  .stat span{font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--dim);text-transform:uppercase}

  .dish{position:relative;width:fit-content;margin:0 auto;background:var(--panel2);
        border:1px solid var(--line);border-radius:8px;padding:10px 10px 12px;
        box-shadow:0 24px 60px rgba(0,0,0,.5), inset 0 0 60px rgba(10,40,38,.5);
        transition:box-shadow .4s}
  .dish.running{box-shadow:0 24px 60px rgba(0,0,0,.5), 0 0 42px rgba(95,227,161,.12),
        inset 0 0 60px rgba(10,40,38,.5)}
  .dish::before,.dish::after{content:"";position:absolute;width:22px;height:22px;pointer-events:none}
  .dish::before{top:-7px;left:-7px;border-top:2px solid var(--amber);border-left:2px solid var(--amber)}
  .dish::after{bottom:-7px;right:-7px;border-bottom:2px solid var(--amber);border-right:2px solid var(--amber)}
  .dish-top{display:flex;align-items:center;gap:8px;margin:0 2px 9px;
            font-family:var(--mono);font-size:10px;letter-spacing:.22em;color:var(--dim)}
  .dot{width:8px;height:8px;border-radius:50%;background:#3d5a55;flex:none;transition:background .3s}
  .dish.running .dot{background:var(--mint);animation:pulse 1s ease-in-out infinite}
  @keyframes pulse{0%,100%{opacity:1;box-shadow:0 0 8px var(--mint)}50%{opacity:.35;box-shadow:none}}
  #state{color:var(--text)}
  .legend{margin-left:auto;display:flex;gap:4px;align-items:center}
  .legend i{width:8px;height:8px;border-radius:2px;display:block}
  .legend i:nth-child(1){background:#ffe95e}
  .legend i:nth-child(2){background:#7df0a4}
  .legend i:nth-child(3){background:#2fbf8f}
  .legend i:nth-child(4){background:#0f8b8d}

  canvas#life{display:block;width:clamp(400px,92vw,576px);aspect-ratio:1/1;
              cursor:crosshair;touch-action:none;background:#0a1518;border:1px solid var(--line)}

  .controls{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:10px;margin-top:22px;user-select:none}
  .btn{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.14em;
       padding:11px 18px;border-radius:6px;background:var(--panel);color:var(--text);
       border:1px solid var(--line);cursor:pointer;
       transition:transform .12s ease, box-shadow .2s ease, background .2s ease}
  .btn:hover{transform:translateY(-2px)}
  .btn:active{transform:translateY(1px) scale(.97)}
  .btn:focus-visible{outline:2px dashed var(--amber);outline-offset:3px}
  .b-mint{border-color:rgba(95,227,161,.55);color:var(--mint)}
  .b-mint:hover{background:rgba(95,227,161,.12);box-shadow:0 8px 20px rgba(95,227,161,.15)}
  .b-cyan{border-color:rgba(122,208,224,.55);color:var(--cyan)}
  .b-cyan:hover{background:rgba(122,208,224,.12);box-shadow:0 8px 20px rgba(122,208,224,.15)}
  .b-coral{border-color:rgba(255,111,94,.55);color:var(--coral)}
  .b-coral:hover{background:rgba(255,111,94,.12);box-shadow:0 8px 20px rgba(255,111,94,.15)}
  #play{background:var(--amber-deep);border-color:var(--amber-deep);color:#241a05;min-width:118px}
  #play:hover{background:var(--amber);box-shadow:0 8px 22px rgba(255,190,90,.3)}
  #play.live{background:var(--mint);border-color:var(--mint);color:#06231a}
  #play.live:hover{box-shadow:0 8px 22px rgba(95,227,161,.3)}

  .tempo{display:flex;align-items:center;gap:9px;font-family:var(--mono);font-size:11px;
         letter-spacing:.18em;color:var(--dim);margin-left:6px}
  .tempo input{width:120px;accent-color:var(--amber);cursor:pointer}
  .tempo b{color:var(--amber);font-variant-numeric:tabular-nums;min-width:52px;text-align:right}

  footer{margin-top:20px;font-family:var(--mono);font-size:11px;letter-spacing:.12em;
         color:var(--dim);text-align:center}
  footer b{color:var(--mint);font-weight:700}

  ::selection{background:var(--amber);color:#241a05}

  @media (prefers-reduced-motion:reduce){
    .bg i,.dish.running .dot{animation:none}
    .btn,.dish{transition:none}
  }
</style>
</head>
<body>
<div class="bg" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div>

<main>
  <header>
    <div>
      <p class="eyebrow">CONWAY'S CELLULAR AUTOMATON · 1970</p>
      <h1>GAME OF <span>LIFE</span></h1>
    </div>
    <div class="readout">
      <div class="stat"><b id="gen">0000</b><span>generation</span></div>
      <div class="stat"><b id="pop">0000</b><span>population</span></div>
    </div>
  </header>

  <section class="dish" id="dish">
    <div class="dish-top">
      <span class="dot"></span>
      <span id="state">PAUSED</span>
      <span>· SPECIMEN 48×48 · EDGES: DEAD</span>
      <span class="legend" title="cell age: newborn → elder"><i></i><i></i><i></i><i></i></span>
    </div>
    <canvas id="life" width="576" height="576"></canvas>
  </section>

  <section class="controls">
    <button id="play"  class="btn" aria-label="Run or pause">▶ RUN</button>
    <button id="step"  class="btn b-mint"  aria-label="Advance one generation">STEP ▸</button>
    <button id="random" class="btn b-cyan" aria-label="Seed random cells">SEED ⚄</button>
    <button id="clear" class="btn b-coral" aria-label="Kill all cells">CLEAR ✕</button>
    <label class="tempo">TEMPO
      <input id="speed" type="range" min="1" max="45" value="12">
      <b id="sval">12 g/s</b>
    </label>
  </section>

  <footer><b>SPACE</b> run/pause · <b>S</b> step · <b>R</b> seed · <b>C</b> clear — click &amp; drag the dish to paint cells (right-click erases)</footer>
</main>

<script>
(function(){
  "use strict";

  // ---------- grid state ----------
  var W = 48, H = 48, CELL = 12;          // 48×48 cells, 576 CSS px dish
  var grid = new Uint8Array(W * H);       // current generation (0/1)
  var next = new Uint8Array(W * H);       // double buffer → simultaneous update
  var age  = new Uint16Array(W * H);      // how long each cell has lived
  var heat = new Float32Array(W * H);     // fading trail of the recently dead
  var gen  = 0;

  // ---------- canvas ----------
  var canvas = document.getElementById('life');
  var ctx = canvas.getContext('2d');
  var CSS = W * CELL;
  (function setup(){
    var dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
    canvas.width = CSS * dpr; canvas.height = CSS * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  })();

  var genEl = document.getElementById('gen'),
      popEl = document.getElementById('pop'),
      stateEl = document.getElementById('state'),
      dishEl = document.getElementById('dish'),
      playBtn = document.getElementById('play'),
      speedEl = document.getElementById('speed'),
      svalEl = document.getElementById('sval');

  // ---------- simulation: B3/S23, dead edges, applied all at once ----------
  function step(){
    for (var y = 0; y < H; y++){
      var yW = y * W;
      for (var x = 0; x < W; x++){
        var n = 0;
        if (y > 0){
          n += grid[yW - W + x];
          if (x > 0)     n += grid[yW - W + x - 1];
          if (x < W - 1) n += grid[yW - W + x + 1];
        }
        if (x > 0)     n += grid[yW + x - 1];
        if (x < W - 1) n += grid[yW + x + 1];
        if (y < H - 1){
          n += grid[yW + W + x];
          if (x > 0)     n += grid[yW + W + x - 1];
          if (x < W - 1) n += grid[yW + W + x + 1];
        }
        var a = grid[yW + x];
        next[yW + x] = (n === 3 || (a === 1 && n === 2)) ? 1 : 0;
      }
    }
    for (var i = 0; i < W * H; i++){
      if (next[i]){ age[i] = grid[i] ? Math.min(age[i] + 1, 900) : 1; heat[i] = 1; }
      else        { heat[i] *= 0.55; age[i] = 0; }
    }
    var t = grid; grid = next; next = t;   // swap buffers
    gen++;
    draw();
  }

  // ---------- rendering ----------
  var STOPS = [[1,255,233,94],[3,125,240,164],[9,47,191,143],[22,15,139,141]];
  function ageColor(a){
    if (a <= 1) return '#ffe95e';
    for (var k = 1; k < STOPS.length; k++){
      if (a <= STOPS[k][0]){
        var A = STOPS[k-1], B = STOPS[k], t = (a - A[0]) / (B[0] - A[0]);
        return 'rgb(' + ((A[1]+(B[1]-A[1])*t)|0) + ',' + ((A[2]+(B[2]-A[2])*t)|0) + ',' + ((A[3]+(B[3]-A[3])*t)|0) + ')';
      }
    }
    return '#0f8b8d';
  }

  function draw(){
    ctx.fillStyle = '#0a1518';
    ctx.fillRect(0, 0, CSS, CSS);

    // grid lines
    ctx.strokeStyle = 'rgba(126,214,196,0.07)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 1; gx < W; gx++){ ctx.moveTo(gx*CELL + .5, 0); ctx.lineTo(gx*CELL + .5, CSS); }
    for (var gy = 1; gy < H; gy++){ ctx.moveTo(0, gy*CELL + .5); ctx.lineTo(CSS, gy*CELL + .5); }
    ctx.stroke();

    // ghost trails of dead cells
    var i, x, y, p = 0;
    for (i = 0; i < W * H; i++){
      if (grid[i]) { p++; continue; }
      if (heat[i] > 0.03){
        x = i % W; y = (i / W) | 0;
        ctx.fillStyle = 'rgba(66,200,164,' + (heat[i] * 0.22).toFixed(3) + ')';
        ctx.fillRect(x*CELL + 1, y*CELL + 1, CELL - 2, CELL - 2);
      }
    }

    // live cells, tinted by age
    for (i = 0; i < W * H; i++){
      if (!grid[i]) continue;
      x = i % W; y = (i / W) | 0;
      if (age[i] <= 1){
        ctx.fillStyle = 'rgba(255,233,94,0.25)';
        ctx.fillRect(x*CELL - 1, y*CELL - 1, CELL + 2, CELL + 2);
      }
      ctx.fillStyle = ageColor(age[i]);
      ctx.fillRect(x*CELL + 1, y*CELL + 1, CELL - 2, CELL - 2);
    }

    // hover reticle
    if (hx >= 0){
      ctx.strokeStyle = 'rgba(255,224,102,0.9)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(hx*CELL + 1.5, hy*CELL + 1.5, CELL - 3, CELL - 3);
    }

    genEl.textContent = String(gen).padStart(4, '0');
    popEl.textContent = String(p).padStart(4, '0');
  }

  // ---------- seeding helpers ----------
  function stamp(rows, ox, oy){
    for (var y = 0; y < rows.length; y++)
      for (var x = 0; x < rows[y].length; x++)
        if (rows[y][x] === 'X'){ var i = (oy + y) * W + (ox + x); grid[i] = 1; age[i] = 1; }
  }
  var GUN = [[0,4],[0,5],[1,4],[1,5],[10,4],[10,5],[10,6],[11,3],[11,7],[12,2],[12,8],
             [13,2],[13,8],[14,5],[15,3],[15,7],[16,4],[16,5],[16,6],[17,5],
             [20,2],[20,3],[20,4],[21,2],[21,3],[21,4],[22,1],[22,5],
             [24,0],[24,1],[24,5],[24,6],[34,2],[34,3],[35,2],[35,3]];
  var PULSAR = ["..XXX...XXX..",".............","X....X.X....X","X....X.X....X",
                "X....X.X....X","..XXX...XXX..",".............","..XXX...XXX..",
                "X....X.X....X","X....X.X....X","X....X.X....X",".............","..XXX...XXX.."];
  var GLIDER = [".X.","..X","XXX"];

  function clearAll(redraw){
    grid.fill(0); next.fill(0); age.fill(0); heat.fill(0); gen = 0;
    if (redraw !== false) draw();
  }
  function randomize(){
    for (var i = 0; i < W * H; i++){ var a = Math.random() < 0.28 ? 1 : 0; grid[i] = a; age[i] = a; heat[i] = 0; }
    gen = 0; draw();
  }
  function seedScene(){
    clearAll(false);
    for (var k = 0; k < GUN.length; k++){ var i = (GUN[k][1] + 5) * W + (GUN[k][0] + 3); grid[i] = 1; age[i] = 1; }
    stamp(PULSAR, 31, 30);
    stamp(GLIDER, 8, 30);
    stamp(GLIDER, 38, 16);
    draw();
  }

  // ---------- painting ----------
  var painting = false, paintVal = 1, hx = -1, hy = -1;
  function cellFromEvent(e){
    var r = canvas.getBoundingClientRect();
    var x = Math.floor((e.clientX - r.left) / r.width * W);
    var y = Math.floor((e.clientY - r.top) / r.height * H);
    return (x < 0 || y < 0 || x >= W || y >= H) ? null : { x: x, y: y };
  }
  function paintCell(x, y){
    var i = y * W + x;
    if (grid[i] === paintVal) return;
    grid[i] = paintVal;
    age[i] = paintVal ? 1 : 0;
    draw();
  }
  canvas.addEventListener('pointerdown', function(e){
    e.preventDefault();
    var c = cellFromEvent(e); if (!c) return;
    canvas.setPointerCapture(e.pointerId);
    painting = true;
    paintVal = e.button === 2 ? 0 : (grid[c.y * W + c.x] ? 0 : 1);
    paintCell(c.x, c.y);
  });
  canvas.addEventListener('pointermove', function(e){
    var c = cellFromEvent(e); if (!c) return;
    if (c.x !== hx || c.y !== hy){ hx = c.x; hy = c.y; if (!painting) draw(); }
    if (painting) paintCell(c.x, c.y);
  });
  canvas.addEventListener('pointerup',     function(){ painting = false; });
  canvas.addEventListener('pointercancel', function(){ painting = false; });
  canvas.addEventListener('pointerleave',  function(){ if (hx !== -1){ hx = -1; hy = -1; draw(); } });
  canvas.addEventListener('contextmenu',   function(e){ e.preventDefault(); });

  // ---------- run loop ----------
  var running = false, lastT = 0, acc = 0, sps = 12;
  function loop(t){
    requestAnimationFrame(loop);
    if (!running){ lastT = t; acc = 0; return; }
    acc += (t - lastT) / 1000; lastT = t;
    var per = 1 / sps, n = 0;
    while (acc >= per && n < 6){ step(); acc -= per; n++; }
    if (acc > per) acc = 0;
  }
  requestAnimationFrame(loop);

  function toggleRun(v){
    running = (v === undefined) ? !running : !!v;
    playBtn.innerHTML = running ? '❚❚ PAUSE' : '▶ RUN';
    playBtn.classList.toggle('live', running);
    stateEl.textContent = running ? 'RUNNING' : 'PAUSED';
    dishEl.classList.toggle('running', running);
  }

  // ---------- controls ----------
  playBtn.addEventListener('click', function(){ toggleRun(); });
  document.getElementById('step').addEventListener('click', function(){ step(); });
  document.getElementById('random').addEventListener('click', randomize);
  document.getElementById('clear').addEventListener('click', function(){ clearAll(); });
  speedEl.addEventListener('input', function(){
    sps = +speedEl.value;
    svalEl.textContent = sps + ' g/s';
  });
  document.querySelectorAll('.btn').forEach(function(b){
    b.addEventListener('click', function(){ b.blur(); });
  });

  window.addEventListener('keydown', function(e){
    var tag = e.target && e.target.tagName;
    if (tag === 'INPUT' || tag === 'BUTTON') return;
    if (e.code === 'Space'){ e.preventDefault(); toggleRun(); }
    else if (e.key === 's' || e.key === 'S') step();
    else if (e.key === 'r' || e.key === 'R') randomize();
    else if (e.key === 'c' || e.key === 'C') clearAll();
  });

  // ---------- public grading API ----------
  window.life = {
    w: W,
    h: H,
    get: function(x, y){
      x |= 0; y |= 0;
      return (x >= 0 && x < W && y >= 0 && y < H) ? grid[y * W + x] : 0;
    },
    set: function(x, y, v){
      x |= 0; y |= 0;
      if (x < 0 || x >= W || y < 0 || y >= H) return;
      var i = y * W + x, nv = v ? 1 : 0;
      if (nv && !grid[i]) age[i] = 1;
      if (!nv) age[i] = 0;
      grid[i] = nv;
      draw();
    },
    step:  function(){ step(); },
    clear: function(){ clearAll(); }
  };

  // ---------- opening specimen: glider gun, pulsar, two stray gliders ----------
  seedScene();
})();
</script>
</body>
</html>
